"use client";

import React, { useState } from 'react';
import { Navbar } from '@/components/Navbar';
import { Hero } from '@/components/Hero';
import { CoupleVsSoloSection } from '@/components/CoupleVsSoloSection';
import { InteractiveSimulator } from '@/components/InteractiveSimulator';
import { MultiCurrencySection } from '@/components/MultiCurrencySection';
import { PwaInstallShowcase } from '@/components/PwaInstallShowcase';
import { TestimonialsSection } from '@/components/TestimonialsSection';
import { FaqSection } from '@/components/FaqSection';
import { Footer } from '@/components/Footer';
import { AuthModal } from '@/components/AuthModal';

export default function LandingPage() {
  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [authModalMode, setAuthModalMode] = useState<'login' | 'register'>('register');

  const handleOpenAuth = (mode: 'login' | 'register') => {
    setAuthModalMode(mode);
    setAuthModalOpen(true);
  };

  const handleScrollToSimulator = () => {
    const el = document.getElementById('simulador');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen bg-[#0b0a15] text-slate-100 flex flex-col selection:bg-purple-600 selection:text-white">
      {/* Top Navbar */}
      <Navbar onOpenAuth={handleOpenAuth} />

      {/* Main Content Area */}
      <main className="flex-1">
        {/* Hero Section con los mockups de los celulares */}
        <Hero
          onOpenAuth={handleOpenAuth}
          onExploreSimulator={handleScrollToSimulator}
        />

        {/* Cuentas Claras en Pareja vs Modo Personal */}
        <CoupleVsSoloSection
          onStartFree={() => handleOpenAuth('register')}
        />

        {/* Simulador Interactivo */}
        <InteractiveSimulator />

        {/* Sección Multi-Moneda */}
        <MultiCurrencySection />

        {/* Instalación PWA */}
        <PwaInstallShowcase />

        {/* Testimonios */}
        <TestimonialsSection />

        {/* Preguntas Frecuentes */}
        <FaqSection />
      </main>

      {/* Footer */}
      <Footer onOpenAuth={handleOpenAuth} />

      {/* Modal de Autenticación */}
      <AuthModal
        isOpen={authModalOpen}
        initialMode={authModalMode}
        onClose={() => setAuthModalOpen(false)}
      />
    </div>
  );
}